import{_ as a,c as e,a2 as r,o}from"./chunks/framework.CO0qOYmW.js";const p=JSON.parse('{"title":"Agent 工作流概述","description":"","frontmatter":{},"headers":[],"relativePath":"ai/06-agent-workflow/01-agent/01-overview.md","filePath":"ai/06-agent-workflow/01-agent/01-overview.md","lastUpdated":1783608971000}'),n={name:"ai/06-agent-workflow/01-agent/01-overview.md"};function i(l,t,d,h,s,g){return o(),e("div",null,t[0]||(t[0]=[r('<h1 id="agent-工作流概述" tabindex="-1">Agent 工作流概述 <a class="header-anchor" href="#agent-工作流概述" aria-label="Permalink to &quot;Agent 工作流概述&quot;">​</a></h1><p>Agent 工作流关注让大模型具备规划、调用工具、观察结果和持续推进任务的能力。企业级 Agent 不只是让模型自由发挥，而是要把工具权限、流程状态、人机协同、失败恢复和审计治理纳入工程体系。</p><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><ul><li><strong>从问答到执行</strong>：让 AI 不只回答问题，还能调用工具完成具体任务。</li><li><strong>从自由对话到可控流程</strong>：通过状态机、工作流和审批机制控制执行边界。</li><li><strong>从单步调用到长任务</strong>：支持多步骤任务、重试、恢复、追踪和人工介入。</li></ul><h2 id="关键能力" tabindex="-1">关键能力 <a class="header-anchor" href="#关键能力" aria-label="Permalink to &quot;关键能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>Agent 循环</td><td>理解规划、行动、观察和反馈的执行模式</td></tr><tr><td>工具调用</td><td>设计 Tool Schema、权限边界和沙箱执行策略</td></tr><tr><td>LangGraph</td><td>使用状态图管理复杂流程、条件路由和 Checkpoint</td></tr><tr><td>多 Agent</td><td>处理任务分派、角色协作、失败恢复和协作治理</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>先理解 Agent 的基本循环和工具调用边界。</li><li>再学习 MCP 和工具权限控制，让 Agent 可以安全接入外部能力。</li><li>最后使用 LangGraph 组织复杂工作流，支持长任务、人机协同和状态恢复。</li></ol>',8)]))}const f=a(n,[["render",i]]);export{p as __pageData,f as default};
